<?php
const MOD = 998244353;

function modinv($a, $mod = MOD) {
    return pow($a, $mod - 2, $mod);
}

function precompute_factorials($max_n) {
    $fact = array_fill(0, $max_n + 1, 1);
    for ($i = 1; $i <= $max_n; $i++) {
        $fact[$i] = $fact[$i - 1] * $i % MOD;
    }
    $inv_fact = array_fill(0, $max_n + 1, 1);
    $inv_fact[$max_n] = modinv($fact[$max_n]);
    for ($i = $max_n - 1; $i >= 0; $i--) {
        $inv_fact[$i] = $inv_fact[$i + 1] * ($i + 1) % MOD;
    }
    return [$fact, $inv_fact];
}

function comb($n, $k, $fact, $inv_fact) {
    if ($n < 0 || $k < 0 || $k > $n) return 0;
    return $fact[$n] * $inv_fact[$k] % MOD * $inv_fact[$n - $k] % MOD;
}

function stars_bars($n, $k, $fact, $inv_fact) {
    if ($n < 0 || $k < 0) return 0;
    if ($k == 0) return ($n == 0) ? 1 : 0;
    return comb($n + $k - 1, $k - 1, $fact, $inv_fact);
}

function main() {
    $line = trim(fgets(STDIN));
    list($p, $s, $r) = array_map('intval', explode(' ', $line));

