            if ($c == 0) continue;
            $min_sum = $k * $a1;
            if ($min_sum > $rem) continue;
            $ways = stars_bars($rem - $min_sum, $p - 1 - $k, $fact, $inv_fact);
            $win = ($win + $c * $ways % MOD) % MOD;
        }
    }

    if ($total == 0) {
        echo 0;
        return;
    }

