<?php

const MOD = 998244353;

function modinv($a) {
    return pow($a, MOD - 2, MOD);
}

function comb($n, $k) {
    if ($k < 0 || $k > $n) return 0;
    $res = 1;
    for ($i = 0; $i < $k; $i++) {
        $res = $res * ($n - $i) % MOD;
        $res = $res * modinv($i + 1) % MOD;
    }
    return $res;
}

function stars_bars($n, $k) {
    // Number of non-negative integer solutions to x_1 + ... + x_k = n
    if ($n < 0) return 0;
    return comb($n + $k - 1, $k - 1);
}

function main() {
    $line = trim(fgets(STDIN));
    list($p, $s, $r) = array_map('intval', explode(' ', $line));

    // Total valid sequences: a_1 >= r, sum a_i = s
    // Let b_1 = a_1 - r, then b_1 >= 0, sum b_i + r = s => sum b_i = s - r
    $total = stars_bars($s - $r, $p);

    if ($total == 0) {
        echo 0;
        return;
    }

    // Count winning sequences
    $win = 0;

    // Case 1: a_1 > max of others
    // a_1 ranges from r to s
    for ($a1 = $r; $a1 <= $s; $a1++) {
        $rem = $s - $a1;
        if ($rem < 0) break;

        // Count sequences where all other p-1 players have score < a1
        // and sum of others = rem
        // Each other player has score in [0, a1-1]
        // Use inclusion-exclusion
        $ways = 0;
        for ($i = 0; $i <= $p - 1; $i++) {
            $sign = ($i % 2 == 0) ? 1 : (MOD - 1);
            $c = comb($p - 1, $i);
            $val = $rem - $i * $a1;
            if ($val < 0) break;
            $ways = ($ways + $sign * $c % MOD * stars_bars($val, $p - 1)) % MOD;
        }
        $win = ($win + $ways) % MOD;
    }

    // Case 2: a_1 = max of others (tie)
    // a_1 ranges from r to s
    for ($a1 = $r; $a1 <= $s; $a1++) {
        $rem = $s - $a1;
        if ($rem < 0) break;

        // Count sequences where at least one other player has score = a1
        // and all others have score <= a1
        // and sum of others = rem
        // Use inclusion-exclusion on players having score >= a1+1 (which we exclude)
        // and then subtract those where all others < a1

        // First, count sequences where all others <= a1 and sum = rem
        $all_le = 0;
        for ($i = 0; $i <= $p - 1; $i++) {
            $sign = ($i % 2 == 0) ? 1 : (MOD - 1);
            $c = comb($p - 1, $i);
            $val = $rem - $i * ($a1 + 1);
            if ($val < 0) break;
            $all_le = ($all_le + $sign * $c % MOD * stars_bars($val, $p - 1)) % MOD;
        }

        // Count sequences where all others < a1 (i.e., <= a1-1) and sum = rem
        $all_lt = 0;
        for ($i = 0; $i <= $p - 1; $i++) {
            $sign = ($i % 2 == 0) ? 1 : (MOD - 1);
            $c = comb($p - 1, $i);
            $val = $rem - $i * $a1;
            if ($val < 0) break;
            $all_lt = ($all_lt + $sign * $c % MOD * stars_bars($val, $p - 1)) % MOD;
        }

        // Sequences where at least one other = a1: all_le - all_lt
        $tie_ways = ($all_le - $all_lt + MOD) % MOD;

        // Probability of winning in tie: 1 / (number of players with max score)
        // If a1 = max, and k others also have a1, then probability = 1/(k+1)
        // We need to sum over all possible k

        // For each k from 1 to p-1 (number of others with score = a1)
        for ($k = 1; $k <= $p - 1; $k++) {
            // Choose k players out of p-1 to have score = a1
            $c = comb($p - 1, $k);
            // Remaining p-1-k players have score in [0, a1-1] and sum = rem - k*a1
            $val = $rem - $k * $a1;
            if ($val < 0) break;

            // Count sequences where remaining players have score in [0, a1-1] and sum = val
            $ways = 0;
            for ($i = 0; $i <= $p - 1 - $k; $i++) {
                $sign = ($i % 2 == 0) ? 1 : (MOD - 1);
                $cc = comb($p - 1 - $k, $i);
                $v = $val - $i * $a1;
                if ($v < 0) break;
                $ways = ($ways + $sign * $cc % MOD * stars_bars($v, $p - 1 - $k)) % MOD;
            }

            $prob = modinv($k + 1);
            $win = ($win + $c * $ways % MOD * $prob) % MOD;
        }
    }

    $ans = $win * modinv($total) % MOD;
    echo $ans;
}

main();

