$MOD = 998244353;

function modinv($a, $mod) {
    return pow($a, $mod - 2, $mod);
}

function comb($n, $k, $mod) {
    if ($k < 0 || $k > $n) return 0;
    if ($k == 0 || $k == $n) return 1;
    $res = 1;
    for ($i = 0; $i < $k; $i++) {
        $res = $res * ($n - $i) % $mod;
        $res = $res * modinv($i + 1, $mod) % $mod;
    }
    return $res;
}

function f($n, $k, $s, $mod) {
    if ($s < 0) return 0;
    if ($n == 0) {
        return ($s == 0) ? 1 : 0;
    }
    $res = 0;
    for ($i = 0; $i <= $k; $i++) {
        $c = comb($n, $i, $mod);
        $sign = ($i % 2 == 0) ? 1 : ($mod - 1);
        $term = $c * $sign % $mod;
        $term = $term * comb($s - $i * ($k + 1) + $n - 1, $n - 1, $mod) % $mod;
        $res = ($res + $term) % $mod;
    }
    return $res;
}

$line = trim(fgets(STDIN));
list($p, $s, $r) = array_map('intval', explode(' ', $line));

if ($s < $r) {
    echo 0;
    exit;
}

