$numerator = 0;
for ($a1 = $r; $a1 <= $s; $a1++) {
    $rem = $s - $a1;
    if ($rem < 0) continue;
    $ways = f($p - 1, $a1 - 1, $rem, $MOD);
    $numerator = ($numerator + $ways) % $MOD;
}

$denominator = $total;
if ($denominator == 0) {
    echo 0;
    exit;
}

$inv_denominator = modinv($denominator, $MOD);
$result = $numerator * $inv_denominator % $MOD;
echo $result;
