<?php

function modinv($a, $mod) {
    return pow($a, $mod - 2, $mod);
}

function main() {
    $mod = 998244353;
    list($p, $s, $r) = array_map('intval', explode(' ', trim(fgets(STDIN))));

    // Precompute factorials and inverse factorials up to s
    $max_n = $s;
    $fact = array_fill(0, $max_n + 1, 1);
    for ($i = 1; $i <= $max_n; $i++) {
        $fact[$i] = $fact[$i - 1] * $i % $mod;
    }
    $inv_fact = array_fill(0, $max_n + 1, 1);
    $inv_fact[$max_n] = modinv($fact[$max_n], $mod);
    for ($i = $max_n - 1; $i >= 0; $i--) {
        $inv_fact[$i] = $inv_fact[$i + 1] * ($i + 1) % $mod;
    }

    // Precompute combinations C(n, k)
    $comb = array();
    for ($n = 0; $n <= $max_n; $n++) {
        $comb[$n] = array_fill(0, $n + 1, 0);
        for ($k = 0; $k <= $n; $k++) {
            $comb[$n][$k] = $fact[$n] * $inv_fact[$k] % $mod * $inv_fact[$n - $k] % $mod;
        }
    }

    // Compute total number of valid sequences
    $total = 0;
    for ($a1 = $r; $a1 <= $s; $a1++) {
        $rem = $s - $a1;
        if ($rem < 0) break;
        if ($p == 1) {
            if ($rem == 0) {
                $total = ($total + 1) % $mod;
            }
        } else {
            if ($rem >= 0) {
                $ways = $comb[$rem + $p - 2][$p - 2];
                $total = ($total + $ways) % $mod;
            }
        }
    }

    // Compute winning sequences
    $win = 0;
    for ($a1 = $r; $a1 <= $s; $a1++) {
        $rem = $s - $a1;
        if ($rem < 0) break;
        if ($p == 1) {
            if ($rem == 0) {
                $win = ($win + 1) % $mod;
            }
            continue;
        }

        // Case 1: All others < a1
        $max_sum = ($a1 - 1) * ($p - 1);
        if ($rem <= $max_sum) {
            $ways = stars_and_bars($rem, $p - 1, $a1 - 1, $comb, $mod);
            $win = ($win + $ways) % $mod;
        }

        // Case 2: At least one equals a1
        $m = $p - 1;
        $max_val = $a1;
        $total_ways = stars_and_bars($rem, $m, $max_val, $comb, $mod);
        $ways_less = stars_and_bars($rem, $m, $a1 - 1, $comb, $mod);
        $ways_eq = ($total_ways - $ways_less + $mod) % $mod;
        $contrib = $ways_eq * modinv($m + 1, $mod) % $mod;
        $win = ($win + $contrib) % $mod;
    }

    $ans = $win * modinv($total, $mod) % $mod;
    echo $ans . "\n";
}

function stars_and_bars($sum, $n, $max_val, $comb, $mod) {
    if ($sum < 0) return 0;
    if ($n == 0) {
        return ($sum == 0) ? 1 : 0;
    }
    $result = 0;
    for ($k = 0; $k <= $n; $k++) {
        $term = $comb[$n][$k];
        $new_sum = $sum - $k * ($max_val + 1);
        if ($new_sum < 0) break;
        $sb = $comb[$new_sum + $n - 1][$n - 1];
        $result = ($result + $term * $sb % $mod) % $mod;
    }
    return $result;
}

