        $res = $res * ($n - $i) % MOD;
        $res = $res * modinv($i + 1) % MOD;
    }
    return $res;
}

function stars_bars($n, $k) {
    if ($n < 0 || $k < 0) return 0;
    if ($k == 0) return ($n == 0) ? 1 : 0;
    return comb($n + $k - 1, $k - 1);
}

